{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Holistic VIP Day</title>
  <meta name='description' content='A practical VIP Day for whole-person care blending nutrition, lifestyle, and integrative modalities. Personal evaluation, a tailored plan, and focused follow-up.'>
  <link rel='stylesheet' href='assets/css/styles.css'>
  <script defer src='assets/js/main.js'></script>
</head>
<body class='theme-bold'>
  <header class='site-header'>
    <div class='wrap nav-wrap'>
      <a class='brand' href='/' aria-label='Home'>
        <svg width='48' height='48' viewBox='0 0 48 48' aria-hidden='true'>
          <defs>
            <linearGradient id='g' x1='0' x2='1'>
              <stop offset='0' stop-color='#6EE7B7'/>
              <stop offset='1' stop-color='#60A5FA'/>
            </linearGradient>
          </defs>
          <rect width='48' height='48' rx='10' fill='url(#g)'></rect>
          <path d='M12 28c4-8 12-8 16 0' stroke='#fff' stroke-width='2' fill='none' stroke-linecap='round'></path>
        </svg>
        <div class='brand-text'>
          <strong>{{BUSINESS_NAME}}</strong>
          <small>{{TAGLINE}}</small>
        </div>
      </a>
      <nav class='primary-nav' aria-label='Main navigation'>
        <a href='services.html'>Offerings</a>
        <a href='conditions.html'>Concerns</a>
        <a href='approach.html'>Our Way</a>
        <a href='pricing.html'>Investment</a>
        <a href='about.html'>Who We Are</a>
        <a href='book.html' class='cta'>Book</a>
        <a href='contact.html'>Contact</a>
      </nav>
      <button class='mobile-toggle' aria-expanded='false' aria-label='Menu'>
        <span></span><span></span><span></span>
      </button>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class='hero wrap' id='hero'>
      <div class='hero-grid'>
        <div class='hero-copy'>
          <h1>VIP Day: An integrated reset for mind, body, and rhythm</h1>
          <p class='lede'>Deep-dive evaluation and a single-day plan built to restore balance, reduce overwhelm, and make progress fast — guided by {{PRACTITIONER_NAME}}, {{CREDENTIALS}}.</p>
          <ul class='hero-meta'>
            <li><strong>Focused:</strong> one intensive day</li>
            <li><strong>Actionable:</strong> take-home plan + resources</li>
            <li><strong>Educational:</strong> learn the "why" and the how</li>
          </ul>
          <p class='no-guarantee'>We emphasize education and whole-person support; individual results vary and no cures are promised.</p>
          <div class='hero-ctas'>
            <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
            <a class='btn ghost' href='about.html'>Meet {{PRACTITIONER_NAME}}</a>
          </div>
        </div>
        <div class='hero-art'>
          <div class='card vip-card'>
            <h3>VIP Day Snapshot</h3>
            <p><strong>City:</strong> {{CITY}}, {{STATE}}</p>
            <p><strong>Session length:</strong> 6–8 hours</p>
            <p><strong>Includes:</strong> intake, focused testing discussion, personalized protocol, resource pack, follow-up call</p>
            <a class='btn small' href='book.html'>Reserve a day</a>
          </div>
        </div>
      </div>
    </section>

    <!-- Ritual (unique order) -->
    <section class='ritual wrap' id='ritual'>
      <h2>Start with a ritual: your VIP day framework</h2>
      <p class='section-sub'>A predictable rhythm helps the body feel safe. We follow a simple ritual to orient assessment and action.</p>
      <div class='three-grid'>
        <article>
          <svg class='icon' viewBox='0 0 24 24' aria-hidden='true'><circle cx='12' cy='12' r='10' fill='#60A5FA'/></svg>
          <h3>Prepare</h3>
          <p>Pre-visit intake and symptom mapping so we prioritize what matters most to you.</p>
        </article>
        <article>
          <svg class='icon' viewBox='0 0 24 24' aria-hidden='true'><rect x='3' y='3' width='18' height='18' rx='4' fill='#6EE7B7'/></svg>
          <h3>Explore</h3>
          <p>Deep discussion across systems — digestion, sleep, stress, inflammation, and energy — to connect the dots.</p>
        </article>
        <article>
          <svg class='icon' viewBox='0 0 24 24' aria-hidden='true'><path d='M2 12h20' stroke='#FBBF24' stroke-width='2' stroke-linecap='round'/></svg>
          <h3>Plan</h3>
          <p>A clear, prioritized protocol you can act on immediately plus educational notes and optional labs if helpful.</p>
        </article>
      </div>
    </section>

    <!-- What to expect -->
    <section class='expect wrap' id='what-to-expect'>
      <h2>What to expect during your VIP Day</h2>
      <p class='section-sub'>A practical walkthrough of the visit so you arrive ready and confident.</p>
      <ol class='expect-list'>
        <li><strong>Warm intake:</strong> a guided review of your history, daily rhythm, and priorities.</li>
        <li><strong>Focused assessment:</strong> systems-based evaluation — digestion, sleep, stress response, and inflammation patterns.</li>
        <li><strong>Education:</strong> explanations of why symptoms occur and how the plan addresses root contributors.</li>
        <li><strong>Personalized plan:</strong> prioritized steps, nutrition, targeted supplements when indicated, movement and sleep guidance.</li>
        <li><strong>Follow-up:</strong> a 30-minute check-in within 2 weeks to refine the plan.</li>
      </ol>
      <p class='note'>Optional: targeted labs can be discussed as educational tools; they are not mandatory and are used selectively to clarify pathways.</p>
    </section>

    <!-- Schedule: clear timeline -->
    <section class='schedule wrap' id='schedule'>
      <h2>Typical VIP Day timeline</h2>
      <div class='timeline'>
        <div class='step'>
          <div class='time'>9:00</div>
          <div class='detail'><strong>Welcome & intake review</strong><br>Review pre-visit forms and set priorities.</div>
        </div>
        <div class='step'>
          <div class='time'>10:00</div>
          <div class='detail'><strong>Systems assessment</strong><br>Deep-dive into digestion, sleep, stress, energy and inflammation clues.</div>
        </div>
        <div class='step'>
          <div class='time'>12:00</div>
          <div class='detail'><strong>Lunch break & integration</strong><br>Time to process and adjust.</div>
        </div>
        <div class='step'>
          <div class='time'>1:00</div>
          <div class='detail'><strong>Targeted interventions</strong><br>Hands-on or guided practices when appropriate.</div>
        </div>
        <div class='step'>
          <div class='time'>3:00</div>
          <div class='detail'><strong>Plan & resources</strong><br>Actionable protocol, handouts, and next steps scheduled.</div>
        </div>
      </div>
      <p class='small'>Start times can shift; the aim is depth and clarity rather than speed.</p>
    </section>

    <!-- Pricing -->
    <section class='pricing wrap' id='pricing'>
      <h2>Investment & what's included</h2>
      <p class='section-sub'>Transparent pricing for a high-touch, educational experience.</p>
      <div class='pricing-grid'>
        <div class='price-card highlight'>
          <h3>VIP Day — Single day</h3>
          <p class='price'>$1,800</p>
          <ul>
            <li>6–8 hour focused visit</li>
            <li>Comprehensive protocol + resources</li>
            <li>30-minute follow-up call</li>
            <li>Optional labs discussed separately</li>
          </ul>
          <a class='btn primary' href='pricing.html'>Learn payment options</a>
        </div>
        <div class='price-card'>
          <h3>Enhanced Package</h3>
          <p class='price'>$2,400</p>
          <ul>
            <li>VIP Day + two 45-minute follow-ups</li>
            <li>Priority scheduling</li>
            <li>Care coordination with allied practitioners</li>
          </ul>
          <a class='btn ghost' href='contact.html'>Discuss custom plan</a>
        </div>
      </div>
      <p class='disclaimer'>Payments may be made by card or bank transfer. Pricing is subject to change; contact us for current availability. We do not promise cures; our work focuses on education and supportive care.</p>
    </section>

    <!-- FAQ -->
    <section class='faq wrap' id='faq'>
      <h2>Frequently asked practical questions</h2>
      <div class='accordion' role='tablist'>
        <button class='acc-item' aria-expanded='false'>How is integrative care different?<span class='toggle'>+</span></button>
        <div class='acc-panel'>We blend evidence-informed modalities with lifestyle and nutrition guidance to treat the whole person. This is educational care that centers your lived experience rather than promising cures.</div>

        <button class='acc-item' aria-expanded='false'>Will you order labs for me?<span class='toggle'>+</span></button>
        <div class='acc-panel'>Labs are optional. When helpful, we discuss targeted tests and their potential to clarify mechanisms. Any testing is an educational tool and decided collaboratively.</div>

        <button class='acc-item' aria-expanded='false'>What if I need follow-up?<span class='toggle'>+</span></button>
        <div class='acc-panel'>The VIP Day includes a 30-minute follow-up. Additional sessions or package add-ons can be scheduled to support ongoing implementation.</div>

        <button class='acc-item' aria-expanded='false'>Do you guarantee improvement?<span class='toggle'>+</span></button>
        <div class='acc-panel'>We focus on practical, prioritized steps and education. Individual responses vary; we cannot guarantee specific treatment outcomes.</div>
      </div>
    </section>

    <!-- CTA -->
    <section class='final-cta wrap' id='cta'>
      <div class='cta-panel'>
        <h2>Ready to reset with a practical, whole-person plan?</h2>
        <p>Reserve a focused VIP Day and leave with clarity, tools, and realistic next steps.</p>
        <a class='btn primary large' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
        <p class='contact-small'>Questions? Call <a href='tel:{{PHONE}}'>{{PHONE}}</a> or email <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a>.</p>
      </div>
    </section>
  </main>

  <footer class='site-footer'>
    <div class='wrap'>
      <div class='footer-grid'>
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p>{{TAGLINE}}</p>
        </div>
        <div>
          <p><strong>Location</strong><br>{{CITY}}, {{STATE}}</p>
          <p><strong>Phone</strong><br><a href='tel:{{PHONE}}'>{{PHONE}}</a></p>
        </div>
        <div>
          <p><strong>Connect</strong><br><a href='book.html'>Book</a> · <a href='contact.html'>Contact</a></p>
        </div>
      </div>
      <small>© <span id='year'></span> {{BUSINESS_NAME}}. All rights reserved. Not medical advice; educational care only.</small>
    </div>
  </footer>

  <svg class='bg-pattern' aria-hidden='true'>
    <use href='assets/img/pattern.svg#pattern'/>
  </svg>
</body>
</html>"} 
