{"path":"assets/css/styles.css","content":"/* Bold Playful theme — single CSS file for visual richness via gradients and SVG pattern */
:root{
  --bg:#0f172a;--card:#0b1220;--accent1:#6EE7B7;--accent2:#60A5FA;--accent3:#FBBF24;--muted:#94a3b8;--glass:rgba(255,255,255,0.04);
  --radius:12px;--max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;color:#e6eef8;background:linear-gradient(180deg,var(--bg) 0%, #071028 100%);}
.wrap{max-width:var(--max);margin:0 auto;padding:36px 20px}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;z-index:40;background:linear-gradient(180deg,rgba(3,7,18,0.6),rgba(3,7,18,0.35));border-bottom:1px solid rgba(255,255,255,0.03)}
.nav-wrap{display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:inherit}
.brand-text strong{display:block;font-size:18px}
.brand-text small{display:block;color:var(--muted);font-size:12px}
.primary-nav{display:flex;gap:14px;align-items:center}
.primary-nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.primary-nav a.cta{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#07203b;font-weight:600}
.mobile-toggle{display:none;background:none;border:0;color:inherit}
.mobile-toggle span{display:block;width:22px;height:2px;background:var(--muted);margin:4px 0}

.hero{padding:60px 20px 48px}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:center}
.hero-copy h1{font-size:34px;margin:0 0 12px;color:#fff}
.lede{color:#dbeafe;margin:0 0 16px}
.hero-meta{display:flex;gap:12px;list-style:none;padding:0;margin:0 0 12px;color:var(--muted)}
.no-guarantee{font-size:13px;color:var(--muted);margin:8px 0}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none}
.btn.primary{background:linear-gradient(90deg,var(--accent2),var(--accent1));color:#05202b;font-weight:700}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted)}
.btn.small{padding:8px 10px}
.btn.large{padding:14px 20px;font-size:18px}
.hero-art .vip-card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:18px;border-radius:14px;border:1px solid rgba(255,255,255,0.03)}

.ritual{padding:36px 20px}
.three-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
.three-grid article{background:var(--card);padding:18px;border-radius:12px}
.icon{width:36px;height:36px}

.expect{padding:28px 20px}
.expect-list{background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);padding:18px;border-radius:12px;list-style:decimal;padding-left:22px;color:var(--muted)}
.note{font-size:13px;color:var(--muted);margin-top:8px}

.schedule{padding:28px 20px}
.timeline{display:flex;flex-direction:column;gap:12px}
.step{display:flex;gap:12px;align-items:flex-start;background:var(--glass);padding:12px;border-radius:10px}
.time{min-width:60px;color:var(--accent2);font-weight:700}
.detail{color:#dbeafe}

.pricing{padding:28px 20px}
.pricing-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.price-card{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.price-card.highlight{border:1px solid rgba(110,231,183,0.18);box-shadow:0 8px 24px rgba(36,52,85,0.6)}
.price{font-size:22px;color:var(--accent1);margin:8px 0}
.disclaimer{font-size:13px;color:var(--muted);margin-top:12px}

.faq{padding:28px 20px}
.accordion{display:block}
.acc-item{width:100%;text-align:left;padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);margin-bottom:8px;background:transparent;color:#e6eef8;display:flex;justify-content:space-between;align-items:center}
.acc-item .toggle{font-weight:700}
.acc-panel{display:none;padding:12px 14px;margin-bottom:8px;background:rgba(255,255,255,0.02);border-radius:8px;color:var(--muted)}

.final-cta{padding:36px 20px}
.cta-panel{background:linear-gradient(90deg, rgba(96,165,250,0.06), rgba(110,231,183,0.04));padding:24px;border-radius:12px;text-align:center}
.contact-small{color:var(--muted);font-size:13px}

.site-footer{border-top:1px solid rgba(255,255,255,0.03);padding:24px 0;margin-top:36px;color:var(--muted)}
.footer-grid{display:flex;gap:18px;justify-content:space-between}

.bg-pattern{position:fixed;right:-8vw;bottom:-8vh;width:60vw;height:60vh;opacity:0.14;pointer-events:none}

@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .three-grid{grid-template-columns:1fr}
  .pricing-grid{grid-template-columns:1fr}
  .primary-nav{display:none}
  .mobile-toggle{display:block}
}

/* Decorative touches */
.hero-art .vip-card::after{content:'';position:absolute;right:40px;top:30px;width:80px;height:80px;background:radial-gradient(circle at 30% 30%, rgba(110,231,183,0.15), transparent 40%);border-radius:50%}
"} 
{"path":"assets/js/main.js","content":"// Simple interactive behaviors: mobile nav, accordion, year update
document.addEventListener('DOMContentLoaded',function(){
  // Mobile nav toggle
  var toggle=document.querySelector('.mobile-toggle');
  var nav=document.querySelector('.primary-nav');
  if(toggle){
    toggle.addEventListener('click',function(){
      var expanded=this.getAttribute('aria-expanded')==='true';
      this.setAttribute('aria-expanded',!expanded);
      if(nav.style.display==='flex'){nav.style.display='none';}else{nav.style.display='flex';nav.style.flexDirection='column';nav.style.background='linear-gradient(180deg,rgba(3,7,18,0.95),rgba(3,7,18,0.9))';nav.style.padding='12px';}
    });
  }

  // Accordion
  var items=document.querySelectorAll('.acc-item');
  items.forEach(function(btn){
    btn.addEventListener('click',function(){
      var expanded=this.getAttribute('aria-expanded')==='true';
      // close all
      items.forEach(function(b){b.setAttribute('aria-expanded','false');var p=b.nextElementSibling;p.style.display='none';p.setAttribute('hidden','');b.querySelector('.toggle').textContent='+'});
      if(!expanded){
        this.setAttribute('aria-expanded','true');
        var panel=this.nextElementSibling;panel.style.display='block';panel.removeAttribute('hidden');this.querySelector('.toggle').textContent='–';
      }
    });
  });

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id=this.getAttribute('href').slice(1);var el=document.getElementById(id);if(el){el.scrollIntoView({behavior:'smooth',block:'start'});}    
    });
  });

  // Year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();
});
"} 
